data class Hand(val text: String, val category: Int, val sequence: List<Int>)

fun evaluate(text: String): Hand {
    val cards = text.split(' ')
    val counts = cards.groupingBy { "23456789TJQKA".indexOf(it[0]) + 2 }.eachCount()
    val ranks = counts.keys.sorted()
    val wheel = ranks == listOf(2, 3, 4, 5, 14)
    val straight = wheel || (ranks.size == 5 && ranks.last() - ranks.first() == 4)
    val flush = cards.all { it[1] == cards[0][1] }
    val largest = counts.values.max()
    val pairs = counts.values.count { it == 2 }
    val category = when {
        straight && flush -> 8
        largest == 4 -> 7
        largest == 3 && pairs == 1 -> 6
        flush -> 5
        straight -> 4
        largest == 3 -> 3
        pairs == 2 -> 2
        pairs == 1 -> 1
        else -> 0
    }
    var sequence = counts.keys.sortedWith(compareByDescending<Int> { counts.getValue(it) }.thenByDescending { it })
    if (wheel && straight) sequence = listOf(5, 4, 3, 2, 1)
    return Hand(text, category, sequence)
}

fun main() {
    val input = listOf("9C 9D 5H QH 2C", "4D AH 3C 5S 2H", "KS 8S 2S JS 6S", "7H 7D KC 7S KD",
        "3H 6C 4S 2D 5C", "JD TC 4H 8C AS", "QC 6D QS 3S 6H", "9H KH 9S 8H 3D")
    val categories = listOf("high card", "one pair", "two pair", "three of a kind", "straight",
        "flush", "full house", "four of a kind", "straight flush")
    val hands = input.map(::evaluate).sortedWith { a, b ->
        var comparison = b.category.compareTo(a.category)
        if (comparison == 0) {
            for (i in a.sequence.indices) {
                comparison = b.sequence[i].compareTo(a.sequence[i])
                if (comparison != 0) break
            }
        }
        comparison
    }
    for ((i, hand) in hands.withIndex()) println("${i + 1}. ${hand.text}: ${categories[hand.category]}")
}
